import AppKit

/// Monochrome **Template**-Logos NUR für die Menüleiste (isTemplate → passt sich
/// Hell/Dunkel an). Aus den gelieferten Schwarz-Weiß-PNGs generiert (Luminanz→Alpha:
/// schwarze Form deckend, weiße Innenflächen als Aussparung), auf ~15 pt Höhe skaliert.
/// Flyout/Umsatzliste nutzen weiterhin die FARBIGEN Assets (ReweLogoAsset etc.).
enum MenuBarLogoAssets {
    static let paypal = load(paypalB64)
    static let rewe   = load(reweB64)
    static let dm     = load(dmB64)
    static let amazon = load(amazonB64)

    /// Menüleisten-Template für eine Slot-Quelle (nil für Bank-Slots).
    static func forSource(_ source: SlotSource) -> NSImage? {
        switch source {
        case .paypal: return paypal
        case .rewe:   return rewe
        case .dm:     return dm
        case .amazon: return amazon
        case .yaxi:   return nil
        }
    }

    private static func load(_ b64: String) -> NSImage? {
        guard let data = Data(base64Encoded: b64.replacingOccurrences(of: "\n", with: "")),
              let img = NSImage(data: data) else { return nil }
        // Auf Menüleisten-Höhe (~15 pt) skalieren, Seitenverhältnis erhalten.
        let ratio = img.size.height > 0 ? img.size.width / img.size.height : 1
        img.size = NSSize(width: 15 * ratio, height: 15)
        img.isTemplate = true
        return img
    }

    private static let paypalB64 = """

"""
    private static let reweB64 = """

"""
    private static let dmB64 = """

"""
    private static let amazonB64 = """

"""
}
